CREATE FUNCTION public.validate_delivery_input(input jsonb) RETURNS void LANGUAGE plpgsql SET search_path=public AS $$ BEGIN
IF nullif(trim(input->'address'->>'street'),'') IS NULL OR nullif(trim(input->'address'->>'number'),'') IS NULL OR nullif(trim(input->'address'->>'neighborhood'),'') IS NULL THEN RAISE EXCEPTION 'Informe bairro, rua e número para entrega'; END IF;
IF length(input::text)>5000 THEN RAISE EXCEPTION 'Endereço muito longo'; END IF;
IF coalesce(nullif(input->>'cashFor',''),'0')::numeric<0 THEN RAISE EXCEPTION 'Troco inválido'; END IF;
IF coalesce(input->'address'->>'latitude','')<>'' OR coalesce(input->'address'->>'longitude','')<>'' THEN IF abs((input->'address'->>'latitude')::numeric)>90 OR abs((input->'address'->>'longitude')::numeric)>180 OR nullif(input->'address'->>'latitude','') IS NULL OR nullif(input->'address'->>'longitude','') IS NULL THEN RAISE EXCEPTION 'Localização inválida'; END IF; END IF;
END $$;
CREATE FUNCTION public.sync_pdv_deliveries() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE o jsonb; prev jsonb; cid uuid; digits text; a jsonb; BEGIN
FOR o IN SELECT value FROM jsonb_array_elements(NEW.data->'orders') WHERE value->>'type'='Delivery' LOOP
SELECT value INTO prev FROM jsonb_array_elements(coalesce(OLD.data->'orders','[]')) WHERE value->>'id'=o->>'id';
IF prev IS NULL OR o->'delivery' IS DISTINCT FROM prev->'delivery' THEN
PERFORM public.validate_delivery_input(o->'delivery'); a=o->'delivery'->'address'; cid=nullif(o->>'customerId','')::uuid;
IF cid IS NULL THEN digits=regexp_replace(coalesce(o->>'customerPhone',''),'[^0-9]','','g'); IF length(digits) IN (10,11) THEN digits='55'||digits; END IF;
IF digits<>'' AND digits !~ '^[1-9][0-9]{9,14}$' THEN RAISE EXCEPTION 'WhatsApp inválido'; END IF;
IF digits<>'' THEN INSERT INTO public.pdv_customers(name,phone) VALUES(left(coalesce(o->>'customer',''),120),digits) ON CONFLICT(phone) DO UPDATE SET updated_at=now() RETURNING id INTO cid;
ELSE INSERT INTO public.pdv_customers(name) VALUES(left(coalesce(o->>'customer',''),120)) RETURNING id INTO cid; END IF; END IF;
IF NOT EXISTS(SELECT 1 FROM public.delivery_addresses WHERE customer_id=cid AND address=a) THEN INSERT INTO public.delivery_addresses(customer_id,address) VALUES(cid,a); END IF;
INSERT INTO public.delivery_orders(order_id,customer_id,customer,phone,address,payment_method,cash_for,created_at,status) VALUES(o->>'id',cid,coalesce(o->>'customer',''),coalesce(o->>'customerPhone',''),a,coalesce(o->'delivery'->>'paymentMethod','Pix'),coalesce(nullif(o->'delivery'->>'cashFor',''),'0')::numeric,to_timestamp((o->>'createdAt')::numeric/1000),CASE WHEN o->>'status'='cancelado' THEN 'Cancelado' WHEN o->>'status'='pronto' THEN 'Pronto para entrega' ELSE 'Aguardando preparo' END) ON CONFLICT(order_id) DO UPDATE SET customer=EXCLUDED.customer,phone=EXCLUDED.phone,address=EXCLUDED.address,payment_method=EXCLUDED.payment_method,cash_for=EXCLUDED.cash_for;
END IF;
UPDATE public.delivery_orders SET status=CASE WHEN o->>'status'='cancelado' THEN 'Cancelado' ELSE 'Pronto para entrega' END WHERE order_id=o->>'id' AND ((o->>'status'='cancelado' AND status<>'Entregue') OR (o->>'status'='pronto' AND status='Aguardando preparo'));
END LOOP; RETURN NEW; END $$;
CREATE TRIGGER pdv_delivery_sync AFTER UPDATE ON public.pdv_state FOR EACH ROW EXECUTE FUNCTION public.sync_pdv_deliveries();
DO $$ DECLARE def text; BEGIN SELECT pg_get_functiondef(oid) INTO def FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname='submit_pdv_operator'; def=replace(def,'''customer'',left(coalesce(request->>''customer'',''''),500)','''delivery'',request->''delivery'',''customerPhone'',request->>''customerPhone'',''customer'',left(coalesce(request->>''customer'',''''),500)'); IF position('''delivery'',request->''delivery''' IN def)=0 THEN RAISE EXCEPTION 'Submission integration not found'; END IF; EXECUTE def; END $$;
CREATE FUNCTION public.delivery_staff() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'cashier') OR public.has_role(auth.uid(),'operator') $$;
CREATE FUNCTION public.read_delivery_board() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE snapshot jsonb; is_admin boolean; result jsonb; BEGIN
is_admin=public.has_role(auth.uid(),'admin'); IF NOT public.delivery_staff() AND NOT public.has_role(auth.uid(),'courier') THEN RAISE EXCEPTION 'Sem permissão'; END IF;
SELECT data INTO snapshot FROM public.pdv_state WHERE id=1;
SELECT coalesce(jsonb_agg(to_jsonb(d)||jsonb_build_object('number',o->'number','items',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',i->>'name','qty',i->'qty','note',i->>'note')),'[]') FROM jsonb_array_elements(coalesce(o->'items','[]')) i),'courier_id',r.courier_id,'total',CASE WHEN is_admin OR d.status NOT IN ('Entregue','Cancelado') THEN t.total END,'due',CASE WHEN is_admin OR d.status NOT IN ('Entregue','Cancelado') THEN greatest(0,t.total-coalesce((SELECT sum((p->>'amount')::numeric) FROM jsonb_array_elements(coalesce(o->'payments','[]')) p),0)) END,'change',CASE WHEN is_admin OR d.status NOT IN ('Entregue','Cancelado') THEN greatest(0,d.cash_for-t.total) END) ORDER BY d.created_at DESC),'[]') INTO result
FROM public.delivery_orders d LEFT JOIN public.delivery_routes r ON r.id=d.route_id LEFT JOIN LATERAL(SELECT value o FROM jsonb_array_elements(snapshot->'orders') WHERE value->>'id'=d.order_id) orders ON true
LEFT JOIN LATERAL(SELECT greatest(0,coalesce((SELECT sum((i->>'qty')::numeric*(i->>'price')::numeric) FROM jsonb_array_elements(coalesce(o->'items','[]')) i),0)-coalesce((o->>'discount')::numeric,0)+coalesce((o->>'fee')::numeric,0)+coalesce((o->>'serviceAmount')::numeric,0)) total) t ON true
WHERE is_admin OR (public.delivery_staff() AND d.status NOT IN ('Entregue','Cancelado')) OR (public.has_role(auth.uid(),'courier') AND EXISTS(SELECT 1 FROM public.delivery_couriers c WHERE c.id=r.courier_id AND c.user_id=auth.uid() AND c.active));
RETURN jsonb_build_object('deliveries',result,'routes',coalesce((SELECT jsonb_agg(to_jsonb(r)) FROM public.delivery_routes r WHERE is_admin OR (public.delivery_staff() AND EXISTS(SELECT 1 FROM public.delivery_orders d WHERE d.route_id=r.id AND d.status NOT IN ('Entregue','Cancelado'))) OR (public.has_role(auth.uid(),'courier') AND EXISTS(SELECT 1 FROM public.delivery_couriers c WHERE c.id=r.courier_id AND c.user_id=auth.uid() AND c.active))),'[]'),'couriers',coalesce((SELECT jsonb_agg(to_jsonb(c)) FROM public.delivery_couriers c WHERE public.delivery_staff() OR (public.has_role(auth.uid(),'courier') AND c.user_id=auth.uid() AND c.active)),'[]')); END $$;
CREATE FUNCTION public.lookup_delivery_addresses(phone_query text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE digits text; BEGIN IF NOT public.delivery_staff() THEN RAISE EXCEPTION 'Sem permissão'; END IF; digits=regexp_replace(phone_query,'[^0-9]','','g'); IF length(digits) IN (10,11) THEN digits='55'||digits; END IF; IF length(digits)<10 THEN RETURN '[]'; END IF; RETURN coalesce((SELECT jsonb_agg(jsonb_build_object('id',a.id,'address',a.address,'name',c.name,'phone',c.phone)) FROM public.delivery_addresses a JOIN public.pdv_customers c ON c.id=a.customer_id WHERE c.phone=digits),'[]'); END $$;
REVOKE ALL ON FUNCTION public.delivery_staff(),public.read_delivery_board(),public.lookup_delivery_addresses(text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.delivery_staff(),public.read_delivery_board(),public.lookup_delivery_addresses(text) TO authenticated;